--
-- Name: accidents_hourly_comparison; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.accidents_hourly_comparison AS
 WITH hourly AS (
         SELECT accidents_by_time.hour,
            accidents_by_time.is_weekend,
            sum(accidents_by_time.accident_count) AS accident_count
           FROM public.accidents_by_time
          WHERE ((accidents_by_time.hour IS NOT NULL) AND (accidents_by_time.is_weekend IS NOT NULL))
          GROUP BY accidents_by_time.hour, accidents_by_time.is_weekend
        )
 SELECT hour,
    is_weekend,
    accident_count,
    round(((100.0 * accident_count) / NULLIF(sum(accident_count) OVER (PARTITION BY is_weekend), (0)::numeric)), 4) AS hour_share_pct
   FROM hourly;


